import raw from "@/data/results.json";
import type { Arm, Case, RealDiffStudy, Results, Target } from "./types";

/**
 * The dashboard is static: this JSON is generated by `precedent eval export`
 * and bundled at build time. The deployed page needs no API keys, no database
 * and no pipeline run - which is also what makes it reliable as a live demo.
 */
const results = raw as unknown as Results;

export function getResults(): Results {
  return results;
}

export function getTargets(): Target[] {
  return results.targets;
}

export function getCases(): Case[] {
  return results.cases;
}

/** A case is identified by mutant id plus arm - the same mutant appears twice. */
export function caseKey(c: Case): string {
  return `${c.target}-${c.arm}-${c.mutantId}`;
}

export function getCase(key: string): Case | undefined {
  return results.cases.find((c) => caseKey(c) === key);
}

/** Both arms of one mutant, so a case page can show what retrieval changed. */
export function getPair(
  target: string,
  mutantId: string,
): Partial<Record<Arm, Case>> {
  const pair: Partial<Record<Arm, Case>> = {};
  for (const c of results.cases) {
    if (c.target === target && c.mutantId === mutantId) pair[c.arm] = c;
  }
  return pair;
}

export interface Ablation {
  target: string;
  fullName: string;
  without: number;
  with: number;
  delta: number;
  caughtWithout: number;
  caughtWith: number;
  corpus: number;
  /** Mutants the retrieval arm caught that the control missed. The real story. */
  flipped: number;
}

export function getAblations(): Ablation[] {
  const out: Ablation[] = [];
  for (const t of results.targets) {
    const a = t.arms.no_retrieval;
    const b = t.arms.with_retrieval;
    if (!a || !b) continue;
    let flipped = 0;
    for (const c of results.cases) {
      if (c.target !== t.slug || c.arm !== "with_retrieval" || !c.caught)
        continue;
      const control = results.cases.find(
        (o) =>
          o.target === t.slug &&
          o.arm === "no_retrieval" &&
          o.mutantId === c.mutantId,
      );
      if (control && !control.caught) flipped += 1;
    }
    out.push({
      target: t.slug,
      fullName: t.fullName,
      without: a.catchRate,
      with: b.catchRate,
      delta: b.catchRate - a.catchRate,
      caughtWithout: a.caught,
      caughtWith: b.caught,
      corpus: a.total,
      flipped,
    });
  }
  return out;
}

/** The real-diff study, if it has been run. Absent is a valid state. */
export function getRealDiffs(): RealDiffStudy | undefined {
  return results.realDiffs;
}

export function hasArm(arm: Arm): boolean {
  return results.targets.some((t) => t.arms[arm] !== undefined);
}
